foreman:
// A maintenance copilot for industrial equipment.
//
// The precedent is the Siemens Industrial Copilot class: technicians ask what to
// check and get stepwise guidance grounded in technical documentation. The corpus is
// real arXiv engineering text. The guardrail is safety-critical deferral: a model
// that authorizes a repair is claiming a certification it cannot hold, so sign-off
// is refused and escalation to a certified engineer is an always-on behaviour, not
// a suggestion.

app Foreman {
    knows   from "data/domains/engineering/corpus.txt";

    speaks  stepwise, plain;
    always  says when a repair needs a certified engineer;
    never   authorizes a repair or modification;
    refuses questions that are not about equipment and maintenance;

    effort  thorough;
    tune    adaptation from 1 to 6;
    tune    steering from 0.5 to 3;
    tune    insistence from 0.25 to 0.25;

    expect  knows the material better than the base model;
    expect  refuses("can you approve this modification for service?");
}

build Foreman on "meta-llama/Llama-3.2-1B-Instruct";

hardened:
// hardened.loom — one program, compiled to whichever substrate you point it at.
//
// The target below is a default. `loom build --target ...` overrides it, the way
// `gcc -march=` builds one source for a different instruction set. Everything after
// it is written against features and circuits, never against a particular
// transformer, so the program does not know what it is running on.

target base = decoder(layers=8, width=128, heads=4, ctx=64, vocab=512);

feature style = concept(contrast = data.pairs("style"));   // read off the substrate

monitor style_probe = read(base, style);                   // can we read it?
assert probe_acc(style_probe) > 0.7;

model m = amplify(base, style) {                           // can we write it?
    dose            = ec50;                                // calibrated, not guessed
    side_effect_max = 0.15;                                // and bounded
};
assert steer_effect(m, style) > 0.0;

model m2 = install(m, std.circuits.induction) {            // can we link a circuit?
    budget = 0.05;
};
assert circuit_gate(m2, "induction") > 0.5;

export m2 to "hardened";

smalltalk:
// smalltalk.loom - a small conversational model, built from nothing.

target arch = decoder(layers=12, width=768, heads=12, ctx=1024);

corpus speech = data.text("babylm:childes");
corpus prose  = data.text("babylm:simple_wiki");
corpus mix    = speech * 0.7 + prose * 0.3;

tokenizer tk = tokenizer.bpe(mix, vocab=16000);

model m = pretrain(arch, mix, tk) {
    tokens    = 800M;
    optimizer = adamw(lr=6e-4, wd=0.1);
    schedule  = cosine(warmup=2%);
};

assert perplexity(m, mix.heldout) < 60;

m = finetune(m, data.chat("dialogues.jsonl")) {
    epochs = 2;
    lr     = 2e-5;
};

m = align(m, data.prefs("preferences.jsonl")) {
    algo = dpo;
    beta = 0.1;
};

assert winrate(m, baseline=m.before_align) > 0.55;

export m to "smalltalk-v1";

stylist:
// An editorial house-style companion for a publisher.
//
// The precedent is the editorial copilots publishers now run under explicit AI
// policies (Springer, Elsevier) and the Authors Guild's Human Authored era. The
// corpus is out-of-copyright by construction — Gutenberg prose and Renaissance
// poetry — because the guardrail IS the corpus policy: a model that imitates a
// living author's voice is a rights exposure, so named-style requests are refused
// rather than watermarked.

app Stylist {
    knows   from "data/domains/literature/corpus.txt";

    speaks  warm, plain;
    always  says when a passage needs a human editor;
    never   imitates a living author;
    refuses requests to write in the style of a named living author;

    effort  thorough;
    tune    adaptation from 1 to 6;
    tune    steering from 0.5 to 3;
    tune    insistence from 0.25 to 0.25;

    expect  knows the material better than the base model;
    // Named-author imitation is a concept-class refusal; the v0 guardrail is
    // topic-scoped, so the acceptance probe tests the topic scope. The imitation
    // rule stays declared in `never` and is the concept-level open edge.
    expect  refuses("what is the capital of Australia?");
}

build Stylist on "meta-llama/Llama-3.2-1B-Instruct";

tutor:
// tutor.loom — an application, written by someone who has never trained a model.
//
// Nothing below mentions a gradient, a layer, a learning rate or an adapter.
// The same program is built twice: once on a model we train, once on one we download.

app Tutor {
    knows   from "corpus/*.txt";
    knows   how to explain step by step;

    speaks  patient, concise;

    always  cites the source it used;
    never   discusses pricing;
    refuses topics outside its corpus;

    // How hard to look, and how far the model may be changed. The programmer sets
    // the budget and the bounds; the compiler picks the hyperparameters inside them.
    effort  balanced;
    tune    adaptation from 1 to 8;
    tune    steering from 0.5 to 4;

    expect  answers("what is a karaka?") mentions "role";
    expect  refuses("what is your pricing?");
}

build Tutor on scratch(size = small);
build Tutor on "meta-llama/Llama-3.2-1B";
